import { ref, computed, onMounted, onUnmounted } from 'vue';
import { useStore } from 'vuex';
import { useRouter } from 'vue-router';
import { socket } from '@/socket';
export default {
  name: 'Account',
  setup() {
    const store = useStore();
    const router = useRouter();
    const loading = ref(false);
    const error = ref('');
    const successMessage = ref('');
    const showPasswordModal = ref(false);
    const showChangePasswordModal = ref(false);
    const showDeleteAccountModal = ref(false);
    const showCurrentPassword = ref(false);
    const showNewPassword = ref(false);
    const showConfirmPassword = ref(false);
    const showPassword = ref(false);
    const showDeletePassword = ref(false);
    const password = ref('');
    const currentPassword = ref('');
    const newPassword = ref('');
    const confirmPassword = ref('');
    const deleteAccountPassword = ref('');
    const currentEditingField = ref(null);
    const isAuthenticated = ref(false);
    const selectedPhoto = ref(null);
    const user = computed(() => store.getters['auth/user']);
    const form = ref({
      username: '',
      nom: '',
      prenom: '',
      date_naissance: '',
      ville: '',
      email: '',
      photo_url: ''
    });
    const editingField = ref({
      username: false,
      nom: false,
      prenom: false,
      date_naissance: false,
      ville: false,
      email: false,
      photo: false
    });
    const formFields = {
      username: {
        label: 'Nom d\'utilisateur',
        validation: value => value.length >= 3 && value.length <= 50,
        editable: true
      },
      email: {
        label: 'Email',
        validation: value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value),
        editable: false
      },
      nom: {
        label: 'Nom',
        validation: value => value.length >= 2 && value.length <= 50,
        editable: true
      },
      prenom: {
        label: 'Prénom',
        validation: value => value.length >= 2 && value.length <= 50,
        editable: true
      },
      date_naissance: {
        label: 'Date de naissance',
        validation: value => {
          const date = new Date(value);
          const now = new Date();
          const age = Math.floor((now - date) / (365.25 * 24 * 60 * 60 * 1000));
          return age >= 18 && age <= 100;
        },
        editable: true
      },
      ville: {
        label: 'Ville',
        validation: value => value.length >= 2 && value.length <= 50,
        editable: true
      },
      photo_url: {
        label: 'Photo de profil',
        validation: value => true,
        editable: true
      }
    };
    const initForm = () => {
      Object.keys(form.value).forEach(key => {
        // Handle date_naissance specially
        if (key === 'date_naissance') {
          if (user.value?.[key]) {
            try {
              const date = new Date(user.value[key]);
              if (!isNaN(date.getTime())) {
                form.value[key] = date.toISOString().split('T')[0];
              } else {
                form.value[key] = ''; // Empty string for invalid date
              }
            } catch (e) {
              form.value[key] = ''; // Empty string if date parsing fails
            }
          } else {
            form.value[key] = ''; // Empty string if no date
          }
        } else {
          // For other fields, use empty string instead of 'Non renseigné'
          form.value[key] = user.value?.[key] || '';
        }
      });
      console.log('Formulaire initialisé avec:', form.value);
    };
    const startEditing = field => {
      editingField.value[field] = true;
    };
    const cancelEditing = field => {
      editingField.value[field] = false;
      form.value[field] = user.value?.[field] || '';
    };
    const promptPasswordAndSave = field => {
      currentEditingField.value = field;
      showPasswordModal.value = true;
      password.value = '';
      setTimeout(() => {
        document.querySelector('input[type="password"]')?.focus();
      }, 100);
    };
    const cancelPasswordModal = () => {
      showPasswordModal.value = false;
      password.value = '';
      currentEditingField.value = null;
    };
    const confirmPasswordAndSave = async () => {
      if (!password.value) {
        error.value = 'Veuillez entrer votre mot de passe';
        return;
      }
      try {
        const field = currentEditingField.value;
        const value = form.value[field];

        // Validation du champ avant envoi
        if (!formFields[field].validation(value)) {
          throw new Error(`La valeur du champ ${formFields[field].label} est invalide`);
        }
        loading.value = true;
        error.value = '';
        successMessage.value = '';
        const userEmail = user.value?.email;
        if (!userEmail) {
          throw new Error('Email de l\'utilisateur non trouvé');
        }
        if (!isAuthenticated.value) {
          throw new Error('Non authentifié');
        }

        // Vérifier que le champ est autorisé à la modification
        const allowedFields = ['username', 'nom', 'prenom', 'date_naissance', 'ville'];
        if (!allowedFields.includes(field)) {
          throw new Error('Ce champ ne peut pas être modifié');
        }
        socket.emit('updateUserField', {
          field,
          value,
          password: password.value
        });
        showPasswordModal.value = false;
        password.value = '';
        currentEditingField.value = null;
      } catch (err) {
        error.value = err.message || 'Une erreur est survenue';
      } finally {
        loading.value = false;
      }
    };
    const formatDate = date => {
      if (!date) return '';
      return new Date(date).toLocaleDateString('fr-FR', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
    };
    const changePassword = async () => {
      if (!currentPassword.value || !newPassword.value || !confirmPassword.value) {
        error.value = 'Veuillez remplir tous les champs';
        return;
      }
      if (newPassword.value !== confirmPassword.value) {
        error.value = 'Les nouveaux mots de passe ne correspondent pas';
        return;
      }
      if (newPassword.value.length < 8) {
        error.value = 'Le nouveau mot de passe doit contenir au moins 8 caractères';
        return;
      }
      try {
        loading.value = true;
        error.value = '';
        socket.emit('changePassword', {
          currentPassword: currentPassword.value,
          newPassword: newPassword.value
        });
        showChangePasswordModal.value = false;
        currentPassword.value = '';
        newPassword.value = '';
        confirmPassword.value = '';
        successMessage.value = 'Mot de passe modifié avec succès';
      } catch (err) {
        error.value = err.message || 'Une erreur est survenue';
      } finally {
        loading.value = false;
      }
    };
    const deleteAccount = async () => {
      if (!deleteAccountPassword.value) {
        error.value = 'Veuillez entrer votre mot de passe';
        return;
      }
      try {
        loading.value = true;
        error.value = '';
        socket.emit('deleteAccount', {
          password: deleteAccountPassword.value
        });

        // La redirection sera gérée par l'événement socket 'accountDeleted'
      } catch (err) {
        error.value = err.message || 'Une erreur est survenue';
      } finally {
        loading.value = false;
      }
    };
    const handlePhotoChange = event => {
      const file = event.target.files[0];
      if (file) {
        selectedPhoto.value = file;
        form.value.photo_url = URL.createObjectURL(file);
      }
    };
    const uploadPhoto = async () => {
      if (!selectedPhoto.value) return;
      const formData = new FormData();
      formData.append('photo', selectedPhoto.value);
      socket.emit('updateProfilePhoto', formData);
    };
    const initializeSocket = () => {
      // Ne pas se reconnecter si déjà authentifié
      if (isAuthenticated.value) {
        return;
      }
      const token = localStorage.getItem('token') || localStorage.getItem('sessionToken');
      if (!token) {
        router.push('/login');
        return;
      }

      // Écouter l'événement de connexion
      socket.on('connect', () => {
        if (!isAuthenticated.value) {
          console.log('Socket connecté, authentification...');
          socket.emit('authenticate', token);
        }
      });

      // Écouter l'événement d'authentification réussie
      socket.on('authenticated', () => {
        if (!isAuthenticated.value) {
          console.log('Socket authentifié, récupération des informations...');
          isAuthenticated.value = true;
          socket.emit('getUserInfo');
        }
      });

      // Écouter les mises à jour des informations utilisateur
      socket.on('userInfo', data => {
        console.log('Informations utilisateur reçues:', data);
        if (data && typeof data === 'object') {
          Object.keys(form.value).forEach(key => {
            if (data[key] !== undefined) {
              form.value[key] = data[key];
            }
          });
          // Mettre à jour le store avec les nouvelles informations
          store.dispatch('auth/updateUser', data);
        }
      });

      // Écouter les succès de mise à jour
      socket.on('userUpdateSuccess', data => {
        console.log('Mise à jour réussie:', data);
        if (data && typeof data === 'object') {
          Object.keys(form.value).forEach(key => {
            if (data[key] !== undefined) {
              form.value[key] = data[key];
            }
          });
          // Mettre à jour le store avec les nouvelles informations
          store.dispatch('auth/updateUser', data);
        }
        Object.keys(editingField.value).forEach(key => {
          editingField.value[key] = false;
        });
        successMessage.value = 'Informations mises à jour avec succès';
        setTimeout(() => {
          successMessage.value = '';
        }, 3000);
      });

      // Écouter les erreurs
      socket.on('error', error => {
        console.error('Erreur socket:', error);
        error.value = error.message || 'Une erreur est survenue';
        if (error.message?.includes('authentification')) {
          isAuthenticated.value = false;
          router.push('/login');
        }
      });

      // Écouter la déconnexion
      socket.on('disconnect', () => {
        console.log('Socket déconnecté');
        isAuthenticated.value = false;
      });

      // Se connecter si pas déjà connecté
      if (!socket.connected) {
        socket.connect();
      }
    };

    // Ajouter les écouteurs d'événements socket pour les nouvelles fonctionnalités
    socket.on('passwordChanged', () => {
      successMessage.value = 'Mot de passe modifié avec succès';
      setTimeout(() => {
        successMessage.value = '';
      }, 3000);
    });
    socket.on('accountDeleted', () => {
      store.dispatch('auth/logout');
      router.push('/login');
    });
    onMounted(() => {
      if (!user.value) {
        router.push('/login');
        return;
      }
      initForm();
      initializeSocket();
    });
    onUnmounted(() => {
      isAuthenticated.value = false;
      const events = ['connect', 'disconnect', 'authenticated', 'userInfo', 'userUpdateSuccess', 'error'];
      events.forEach(event => {
        socket.off(event);
      });
      socket.disconnect();
    });
    return {
      loading,
      error,
      successMessage,
      form,
      editingField,
      formFields,
      showPasswordModal,
      password,
      showChangePasswordModal,
      showDeleteAccountModal,
      currentPassword,
      newPassword,
      confirmPassword,
      deleteAccountPassword,
      showCurrentPassword,
      showNewPassword,
      showConfirmPassword,
      showPassword,
      showDeletePassword,
      startEditing,
      cancelEditing,
      promptPasswordAndSave,
      cancelPasswordModal,
      confirmPasswordAndSave,
      formatDate,
      changePassword,
      deleteAccount,
      handlePhotoChange,
      uploadPhoto
    };
  }
};
